package com.mps.assignment.service;
import com.mps.assignment.dto.AssignmentDtos.ConflictView; import com.mps.assignment.model.AssignmentStatus; import com.mps.assignment.repository.AssignmentRepository; import com.mps.auth.model.*; import com.mps.availability.model.AvailabilityStatus; import com.mps.availability.repository.AvailabilityEntryRepository; import com.mps.schedule.model.ScheduleEvent; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ConflictDetectionService { private final AssignmentRepository assignments; private final AvailabilityEntryRepository availability; public ConflictDetectionService(AssignmentRepository a,AvailabilityEntryRepository v){assignments=a;availability=v;}
 public List<ConflictView> detect(UUID org,ScheduleEvent schedule,AppUser user){List<ConflictView> out=new ArrayList<>(); if(user==null){out.add(new ConflictView("UNFILLED","Assignment has no assignee.",true));return out;} if(user.getStatus()!=UserStatus.ACTIVE)out.add(new ConflictView("INACTIVE_USER","Assignee is not active.",true)); boolean overlap=assignments.existsByOrganizationIdAndAssigneeIdAndStatusNotInAndScheduleStartAtLessThanAndScheduleEndAtGreaterThan(org,user.getId(),List.of(AssignmentStatus.CANCELLED,AssignmentStatus.ARCHIVED),schedule.getEndAt(),schedule.getStartAt()); if(overlap)out.add(new ConflictView("OVERLAP","Assignee has an overlapping active assignment.",true)); boolean unavailable=availability.existsByOrganizationIdAndUserIdAndStatusAndStartAtLessThanAndEndAtGreaterThan(org,user.getId(),AvailabilityStatus.UNAVAILABLE,schedule.getEndAt(),schedule.getStartAt()); if(unavailable)out.add(new ConflictView("UNAVAILABLE","Assignee declared unavailability for this period.",false)); return out;}
 public boolean hasBlocking(List<ConflictView> conflicts){return conflicts.stream().anyMatch(ConflictView::blocking);}
}
